  select AT.article_id from article_tags AT
  join tags T on T.id = AT.tag_id
  where T.name = #{tag}
)

AND A.id in (
  select AF.article_id from article_favorites AF
  join users AFU on AFU.id = AF.user_id
  where AFU.username = #{favoritedBy}
)

